const inJson = $json || {};
const body = (inJson.body && typeof inJson.body === 'object') ? inJson.body : {};

const pick = (a, b, fallback = '') => {
  if (a !== undefined && a !== null && String(a).trim() !== '') return String(a).trim();
  if (b !== undefined && b !== null && String(b).trim() !== '') return String(b).trim();
  return fallback;
};

return [{
  json: {
    backend_base_url: pick(inJson.backend_base_url, body.backend_base_url, 'http://127.0.0.1:8001'),
    service_email: pick(inJson.service_email, body.service_email, 'james.bond@gmail.com'),
    service_password: pick(inJson.service_password, body.service_password, 'Martini@007'),
    recipient_email: pick(inJson.recipient_email, body.recipient_email, 'sankalp.bajpai@amzur.com'),
    email_subject: pick(inJson.email_subject, body.email_subject, 'AI Excel Analysis Results'),

    // Optional overrides. If omitted, workflow auto-detects latest values from backend APIs.
    chat_thread_id: pick(inJson.chat_thread_id, body.chat_thread_id, ''),
    file_id: pick(inJson.file_id, body.file_id, ''),
    question: pick(inJson.question, body.question, '')
  }
}];

const row = $json;
const headers = row.headers || {};
let setCookie = headers['set-cookie'] || headers['Set-Cookie'];
if (Array.isArray(setCookie)) setCookie = setCookie[0];

const authCookie = setCookie ? String(setCookie).split(';')[0] : '';
const accessToken = row.access_token || row.body?.access_token || '';
const authBearer = accessToken ? `Bearer ${accessToken}` : '';

if (!authCookie && !authBearer) {
  throw new Error('Login succeeded but no set-cookie or access_token found.');
}

return [{ json: { auth_cookie: authCookie, auth_bearer: authBearer } }];

const manualThread = ($node['Normalize Input'].json.chat_thread_id || '').trim();

const normalizeThreads = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== 'object') return [];

  const keys = ['threads', 'items', 'data', 'results'];
  for (const key of keys) {
    if (Array.isArray(raw[key])) return raw[key];
  }

  if (Array.isArray(raw.body)) return raw.body;

  if (raw.body && typeof raw.body === 'object') {
    for (const key of keys) {
      if (Array.isArray(raw.body[key])) return raw.body[key];
    }
    if (raw.body.id) return [raw.body];
  }

  if (raw.id) return [raw];
  return [];
};

let threads = normalizeThreads($json.body ?? $json);

if (!threads.length) {
  const merged = [];
  for (const item of $input.all()) {
    merged.push(...normalizeThreads(item.json));
  }
  threads = merged;
}

const seen = new Set();
threads = threads.filter((t) => {
  const id = String(t?.id || '').trim();
  if (!id || seen.has(id)) return false;
  seen.add(id);
  return true;
});

let chatThreadId = manualThread;
let threadTitle = '';

if (!chatThreadId) {
  if (!threads.length) {
    throw new Error('No chat threads found for this user.');
  }

  const sorted = [...threads].sort((a, b) => {
    const ta = Date.parse(a?.created_at || a?.updated_at || '') || 0;
    const tb = Date.parse(b?.created_at || b?.updated_at || '') || 0;
    return tb - ta;
  });

  const picked = sorted[0] || threads[0];
  chatThreadId = String(picked?.id || '').trim();
  threadTitle = String(picked?.title || '').trim();
} else {
  const matched = threads.find((t) => String(t?.id || '').trim() === chatThreadId);
  if (matched) threadTitle = String(matched?.title || '').trim();
}

if (!chatThreadId) {
  throw new Error('Unable to resolve chat_thread_id.');
}

return [{ json: { chat_thread_id: chatThreadId, thread_title: threadTitle } }];

const manualQuestion = ($node['Normalize Input'].json.question || '').trim();
const manualFileId = ($node['Normalize Input'].json.file_id || '').trim();
const threadId = $node['Resolve Latest Thread'].json.chat_thread_id;

const normalizeMessages = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== 'object') return [];

  const keys = ['messages', 'items', 'data', 'results'];
  for (const key of keys) {
    if (Array.isArray(raw[key])) return raw[key];
  }

  if (Array.isArray(raw.body)) return raw.body;

  if (raw.body && typeof raw.body === 'object') {
    for (const key of keys) {
      if (Array.isArray(raw.body[key])) return raw.body[key];
    }
    if (raw.body.role) return [raw.body];
  }

  if (raw.role) return [raw];
  return [];
};

const normalizeAttachments = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== 'object') return [];

  if (Array.isArray(raw.attachments)) return raw.attachments;
  if (raw.body && typeof raw.body === 'object' && Array.isArray(raw.body.attachments)) {
    return raw.body.attachments;
  }

  return [];
};

let messages = normalizeMessages($json.body ?? $json);
let threadAttachments = normalizeAttachments($json.body ?? $json);

if (!messages.length || !threadAttachments.length) {
  const mergedMessages = [];
  const mergedAttachments = [];
  for (const item of $input.all()) {
    mergedMessages.push(...normalizeMessages(item.json));
    mergedAttachments.push(...normalizeAttachments(item.json));
  }
  if (!messages.length) messages = mergedMessages;
  if (!threadAttachments.length) threadAttachments = mergedAttachments;
}

const seenMessages = new Set();
messages = messages.filter((m) => {
  const id = String(m?.id || '').trim();
  if (!id || seenMessages.has(id)) return false;
  seenMessages.add(id);
  return true;
});

messages.sort((a, b) => {
  const ta = Date.parse(a?.created_at || a?.updated_at || '') || 0;
  const tb = Date.parse(b?.created_at || b?.updated_at || '') || 0;
  return ta - tb;
});

const seenAttachments = new Set();
threadAttachments = threadAttachments.filter((a) => {
  const id = String(a?.id || '').trim();
  if (!id || seenAttachments.has(id)) return false;
  seenAttachments.add(id);
  return true;
});

threadAttachments.sort((a, b) => {
  const ta = Date.parse(a?.created_at || '') || 0;
  const tb = Date.parse(b?.created_at || '') || 0;
  return ta - tb;
});

let latestUserMessage = null;
for (let i = messages.length - 1; i >= 0; i -= 1) {
  const m = messages[i];
  if ((m.role || '').toLowerCase() === 'user' && String(m.content || '').trim() !== '') {
    latestUserMessage = m;
    break;
  }
}

let latestTableAttachment = null;
for (let i = threadAttachments.length - 1; i >= 0; i -= 1) {
  const a = threadAttachments[i] || {};
  if ((a.file_type || '').toLowerCase() === 'table' && String(a.id || '').trim() !== '') {
    latestTableAttachment = a;
    break;
  }
}

if (!latestTableAttachment) {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const msg = messages[i] || {};
    const attachments = Array.isArray(msg.attachments) ? msg.attachments : [];
    for (let j = attachments.length - 1; j >= 0; j -= 1) {
      const a = attachments[j] || {};
      if ((a.file_type || '').toLowerCase() === 'table' && String(a.id || '').trim() !== '') {
        latestTableAttachment = a;
        break;
      }
    }
    if (latestTableAttachment) break;
  }
}

const question = manualQuestion || String(latestUserMessage?.content || '').trim();
const fileId = manualFileId || String(latestTableAttachment?.id || '').trim();

if (!question) {
  throw new Error('Unable to resolve latest user question. Pass question explicitly or ensure thread has user messages.');
}

if (!fileId) {
  throw new Error('Unable to resolve latest table file_id. Pass file_id explicitly or ensure thread has at least one uploaded table attachment.');
}

return [{
  json: {
    chat_thread_id: threadId,
    question,
    file_id: fileId,
    source_user_message_id: latestUserMessage?.id || '',
    source_attachment_name: latestTableAttachment?.file_name || ''
  }
}];

