const payload = $json.body ?? $json;
const resolved = $node['Resolve Latest Context'].json;

const question = resolved.question;
const threadId = resolved.chat_thread_id || '';

const analysis = payload.answer
  ?? payload.analysis
  ?? payload.response
  ?? payload.result?.answer
  ?? payload.result?.analysis
  ?? JSON.stringify(payload.result ?? payload, null, 2);

const shape = payload.dataframe_shape
  ?? payload.result?.dataframe_shape
  ?? payload.shape
  ?? 'N/A';

let columns = payload.columns
  ?? payload.result?.columns
  ?? payload.result?.column_names
  ?? [];

if (!Array.isArray(columns)) {
  if (typeof columns === 'string') {
    columns = columns.split(',').map(c => c.trim()).filter(Boolean);
  } else {
    columns = [];
  }
}

const columnsText = columns.length ? columns.join(', ') : 'N/A';

const textBody = [
  `Question: ${question}`,
  '',
  'AI Analysis:',
  String(analysis),
  '',
  `DataFrame Shape: ${String(shape)}`,
  `Columns: ${columnsText}`,
  `Thread ID: ${threadId || 'N/A'}`,
  `File ID: ${resolved.file_id || 'N/A'}`,
  resolved.source_attachment_name ? `Source File: ${resolved.source_attachment_name}` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    text_body: textBody,
    analysis_text: String(analysis),
    thread_id: threadId,
    question,
    file_id: resolved.file_id
  }
}];
